"use client"

import * as React from "react"

import {
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { cn } from "@/lib/utils"

import {
  getColumnPinStyle,
  pinEdgeShadowClass,
  type PinableColumn,
  type PinTable,
} from "./lib"

export type DataTableGridProps = React.ComponentProps<"div"> & {
  /** Cap vertical height so the header can stick while scrolling. */
  maxHeight?: number | string
}

function DataTableGrid({
  className,
  maxHeight = "min(28rem, 70vh)",
  children,
  style,
  ...props
}: DataTableGridProps) {
  return (
    <div
      data-slot="data-table-grid"
      className={cn(
        "w-full overflow-hidden rounded-[12px] border border-border/70 bg-card shadow-xs",
        className
      )}
      style={style}
      {...props}
    >
      <div
        data-slot="data-table-grid-viewport"
        className="relative w-full overflow-auto overscroll-contain"
        style={{ maxHeight }}
      >
        {children}
      </div>
    </div>
  )
}

export type DataTableGridTableProps = React.ComponentProps<"table"> & {
  /** Prefer `table.getTotalSize()` so resized columns keep layout. */
  totalSize?: number
}

function DataTableGridTable({
  className,
  totalSize,
  style,
  ...props
}: DataTableGridTableProps) {
  return (
    <table
      data-slot="data-table-grid-table"
      className={cn("w-full caption-bottom border-separate border-spacing-0 text-sm", className)}
      style={{
        width: totalSize,
        tableLayout: totalSize != null ? "fixed" : undefined,
        ...style,
      }}
      {...props}
    />
  )
}

function DataTableGridHeader({
  className,
  ...props
}: React.ComponentProps<typeof TableHeader>) {
  return (
    <TableHeader
      data-slot="data-table-grid-header"
      className={cn(
        "sticky top-0 z-30 bg-card [&_tr]:border-b [&_tr]:border-border/70",
        className
      )}
      {...props}
    />
  )
}

export type DataTableGridHeadProps = React.ComponentProps<
  typeof TableHead
> & {
  column: PinableColumn
  table: PinTable
}

function DataTableGridHead({
  column,
  table,
  className,
  style,
  ...props
}: DataTableGridHeadProps) {
  const pinned = column.getIsPinned?.() ?? false
  const pinStyle = getColumnPinStyle(column)
  return (
    <TableHead
      data-slot="data-table-grid-head"
      data-pinned={pinned || undefined}
      className={cn(
        "sticky top-0 z-20 bg-card",
        pinned && "z-30",
        pinEdgeShadowClass(column, table),
        className
      )}
      style={{
        ...pinStyle,
        position: "sticky",
        top: 0,
        ...style,
      }}
      {...props}
    />
  )
}

export type DataTableGridCellProps = React.ComponentProps<
  typeof TableCell
> & {
  column: PinableColumn
  table: PinTable
}

function DataTableGridCell({
  column,
  table,
  className,
  style,
  ...props
}: DataTableGridCellProps) {
  const pinned = column.getIsPinned?.() ?? false
  return (
    <TableCell
      data-slot="data-table-grid-cell"
      data-pinned={pinned || undefined}
      className={cn(
        "bg-card",
        pinned && "z-10",
        pinEdgeShadowClass(column, table),
        className
      )}
      style={{ ...getColumnPinStyle(column), ...style }}
      {...props}
    />
  )
}

export {
  DataTableGrid,
  DataTableGridTable,
  DataTableGridHeader,
  DataTableGridHead,
  DataTableGridCell,
  TableBody as DataTableGridBody,
  TableRow as DataTableGridRow,
}

"use client"

import {
  ArrowDownIcon,
  ArrowUpDownIcon,
  ArrowUpIcon,
  PinIcon,
  PinOffIcon,
} from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { cn } from "@/lib/utils"

import type { ColumnPinningPosition } from "./lib"

export type SortableColumn = {
  getCanSort?: () => boolean
  getIsSorted?: () => false | "asc" | "desc"
  getToggleSortingHandler?: () =>
    | ((event: unknown) => void)
    | undefined
}

export type PinColumn = {
  getCanPin?: () => boolean
  getIsPinned?: () => ColumnPinningPosition
  pin?: (position: ColumnPinningPosition) => void
}

export type DataTableColumnHeaderProps = {
  title: string
  column: SortableColumn & PinColumn
  className?: string
  /** Hide the pin menu (sort-only header). */
  disablePinning?: boolean
}

function DataTableColumnHeader({
  title,
  column,
  className,
  disablePinning = false,
}: DataTableColumnHeaderProps) {
  const sorted = column.getIsSorted?.() ?? false
  const canSort = Boolean(column.getCanSort?.())
  const canPin =
    !disablePinning &&
    Boolean(column.getCanPin?.()) &&
    typeof column.pin === "function"
  const pinned = column.getIsPinned?.() ?? false

  if (!canSort && !canPin) {
    return (
      <span className={cn("text-sm font-medium", className)}>{title}</span>
    )
  }

  return (
    <div
      data-slot="data-table-column-header"
      className={cn("flex items-center gap-1", className)}
    >
      {canSort ? (
        <Button
          type="button"
          variant="ghost"
          size="sm"
          className="-ms-2 h-8 gap-1.5 px-2 font-medium"
          onClick={column.getToggleSortingHandler?.()}
        >
          <span className="truncate">{title}</span>
          {sorted === "asc" ? (
            <ArrowUpIcon className="size-3.5 opacity-70" aria-hidden />
          ) : sorted === "desc" ? (
            <ArrowDownIcon className="size-3.5 opacity-70" aria-hidden />
          ) : (
            <ArrowUpDownIcon className="size-3.5 opacity-50" aria-hidden />
          )}
        </Button>
      ) : (
        <span className="truncate px-1 text-sm font-medium">{title}</span>
      )}

      {canPin ? (
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button
              type="button"
              variant="ghost"
              size="icon-xs"
              className="size-8 shrink-0 text-muted-foreground"
              aria-label={`Pin ${title}`}
            >
              {pinned ? (
                <PinIcon className="size-3.5" aria-hidden />
              ) : (
                <PinOffIcon className="size-3.5 opacity-60" aria-hidden />
              )}
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="start" className="min-w-40">
            <DropdownMenuItem
              className="cursor-pointer"
              disabled={pinned === "start"}
              onSelect={() => column.pin?.("start")}
            >
              Pin start
            </DropdownMenuItem>
            <DropdownMenuItem
              className="cursor-pointer"
              disabled={pinned === "end"}
              onSelect={() => column.pin?.("end")}
            >
              Pin end
            </DropdownMenuItem>
            {pinned ? (
              <>
                <DropdownMenuSeparator />
                <DropdownMenuItem
                  className="cursor-pointer"
                  onSelect={() => column.pin?.(false)}
                >
                  Unpin
                </DropdownMenuItem>
              </>
            ) : null}
          </DropdownMenuContent>
        </DropdownMenu>
      ) : null}
    </div>
  )
}

export { DataTableColumnHeader }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

export type ResizeHeader = {
  getResizeHandler: (context?: Document) => (event: unknown) => void
  column: {
    getCanResize: () => boolean
    getIsResizing: () => boolean
  }
}

export type DataTableResizeHandleProps = {
  header: ResizeHeader
  className?: string
}

function DataTableResizeHandle({
  header,
  className,
}: DataTableResizeHandleProps) {
  if (!header.column.getCanResize()) return null

  const resizing = header.column.getIsResizing()

  return (
    <span
      data-slot="data-table-resize-handle"
      data-resizing={resizing ? "" : undefined}
      role="separator"
      aria-orientation="vertical"
      aria-hidden
      className={cn(
        "absolute inset-y-0 end-0 z-30 w-1 cursor-col-resize touch-none select-none",
        "after:absolute after:inset-y-1 after:end-0 after:w-px after:bg-border/80",
        "hover:after:bg-primary/50 data-[resizing]:after:bg-primary",
        className
      )}
      onDoubleClick={(event) => {
        event.preventDefault()
        event.stopPropagation()
      }}
      onMouseDown={header.getResizeHandler() as React.MouseEventHandler}
      onTouchStart={header.getResizeHandler() as React.TouchEventHandler}
    />
  )
}

export { DataTableResizeHandle }

import type * as React from "react"

export type ColumnPinningPosition = false | "start" | "end"

export type PinableColumn = {
  id: string
  getIsPinned?: () => ColumnPinningPosition
  getStart?: (position?: ColumnPinningPosition | "center") => number
  getAfter?: (position?: ColumnPinningPosition | "center") => number
  getSize: () => number
}

/**
 * Any TanStack `useTable()` instance.
 * Typed as `object` so tables without `columnPinningFeature` still type-check
 * (a type with only optional fields is a TS “weak type”).
 */
export type PinTable = object

type PinTableHelpers = {
  getStartVisibleLeafColumns?: () => Array<{ id: string }>
  getEndVisibleLeafColumns?: () => Array<{ id: string }>
}

/** Sticky offsets for a pinned column (logical start/end). */
export function getColumnPinStyle(
  column: PinableColumn
): React.CSSProperties {
  const pinned = column.getIsPinned?.() ?? false
  if (!pinned) {
    return { width: column.getSize() }
  }

  const style: React.CSSProperties = {
    position: "sticky",
    width: column.getSize(),
    zIndex: 1,
  }

  if (pinned === "start") {
    style.insetInlineStart = column.getStart?.("start") ?? 0
  } else {
    style.insetInlineEnd = column.getAfter?.("end") ?? 0
  }

  return style
}

/** True when this column is the edge against the scrollable center. */
export function isPinEdgeColumn(
  column: PinableColumn,
  table: PinTable
): boolean {
  const pinned = column.getIsPinned?.() ?? false
  if (!pinned) return false
  const helpers = table as PinTableHelpers
  const leaves =
    pinned === "start"
      ? (helpers.getStartVisibleLeafColumns?.() ?? [])
      : (helpers.getEndVisibleLeafColumns?.() ?? [])
  if (leaves.length === 0) return false
  if (pinned === "start") {
    return leaves[leaves.length - 1]?.id === column.id
  }
  return leaves[0]?.id === column.id
}

export function pinEdgeShadowClass(
  column: PinableColumn,
  table: PinTable
): string | undefined {
  if (!isPinEdgeColumn(column, table)) return undefined
  const pinned = column.getIsPinned?.() ?? false
  if (pinned === "start") {
    return "shadow-[4px_0_8px_-4px_rgba(0,0,0,0.14)] dark:shadow-[4px_0_8px_-4px_rgba(0,0,0,0.45)]"
  }
  if (pinned === "end") {
    return "shadow-[-4px_0_8px_-4px_rgba(0,0,0,0.14)] dark:shadow-[-4px_0_8px_-4px_rgba(0,0,0,0.45)]"
  }
  return undefined
}
